//TO handle config + RUN states 
//to Differentiate it and disable and enable the Engines.
//Note : bfrTX=data[Cnt]; So dont make write data same way as ID 
//Just write ID and Data in reverse order from lsb to msb in apb mode
module MAINFSM(CAN_CLK,CAN_RST,done_RXs,done_TXs,RX,TX,PCLK, PRESETn, PSEL, PENABLE, PWRITE, PADDR, PWDATA, PSLVERR, PRDATA, PREADY);
//can inputs
input CAN_CLK,CAN_RST;
input RX;
//srst is generated by APBCDC
//rec TEC is geenrated by ERRORhandler 
//TIMING regs and 
//can outptus
output reg TX;
//interrupts
output wire done_RXs,done_TXs;
wire [2:0]Mode;
wire        IDE_rec;
wire        RTR_rec;
wire [3:0]  D_Len_rec;
wire [63:0] TOFILTERd;
wire [28:0] TOFILTERI;
reg RXBUS;
wire RXBUSs;
wire Tq,req_Error_TX,req_Error_RX,Sampled_din,TXen,RXen,SRST,ErrState,imTX,TX_from_trans,AckTakeOver,OvlState,TX_from_Err;
wire [3:0]RXSTATES,TXSTATES;
wire [8:0]TEC,REC;


//apb write to this
//6 x 32 bits 
//copy from REGBANK_can to avoid read while writing 
wire [3:0]TPROP,TSEG1,TSEG2,TPROP_Amender,TSEG1_Amender,TSEG2_Amender;
wire [28:0] ID_TX;
wire        IDE_TX;
wire        RTR_TX;
wire [63:0] data_TX;
wire [3:0]  D_Len_TX;
wire        TRANSMIT;
wire [4:0] BRP;
wire [2:0] SJW,SJW_Amender;

//apb inputs
input PCLK, PRESETn, PSEL, PENABLE, PWRITE;
input [5:0] PADDR;
input [31:0] PWDATA;

//apb outputs
    output wire        PREADY;
    output wire        PSLVERR;

    output wire [31:0] PRDATA;


//TX routoing ending based on Mode TX wil be the endpoint to be snent depends on Mode and REC and TEC
always@(*)begin
if(Mode[0]==1'b1)begin//Soft Reset
TX=1;
RXBUS=1;
end
else if(Mode==2'b10) begin//Listen only
    TX=1;
    RXBUS=RXBUSs;
end
else if(Mode==3'b100) begin//loopback
RXBUS=TX;
TX=(TEC>=256)?1'b1:(AckTakeOver&&TX_from_Err&&TX_from_trans);
end
else begin//normal
RXBUS=RXBUSs;
TX=(TEC>=256)?1'b1:(AckTakeOver&&TX_from_Err&&TX_from_trans);
    end
end


//RXBUS routing pending final end point ised will be RXBUS  start point depends on Mode
TFF TFF_RXB(.D(RX),.rst(CAN_RST),.clk(Tq),.q(RXBUSs));

TFF done_RX_TFF(.D(done_RX),.rst(PRESETn),.clk(PCLK),.q(done_RXs));
TFF done_TX_TFF(.D(done_TX),.rst(PRESETn),.clk(PCLK),.q(done_TXs));

// TPROP: legal range 1 to 8 (4 bits)
assign TPROP_Amender = (TPROP > 4'd8) ? 4'd8 : 
                       (TPROP == 4'd0) ? 4'd1 : 
                       TPROP;

// TSEG1: legal range 1 to 8 (4 bits)
assign TSEG1_Amender = (TSEG1 > 4'd8) ? 4'd8 : 
                       (TSEG1 == 4'd0) ? 4'd1 : 
                       TSEG1;

// TSEG2: legal range 1 to 8 (4 bits)
assign TSEG2_Amender = (TSEG2 > 4'd8) ? 4'd8 : 
                       (TSEG2 == 4'd0) ? 4'd1 : 
                       TSEG2;




//in application of certain changes(timing) remove TX pin from the port -drive 1



TXMachine tx1 (
    .rst(CAN_RST),
    .srst(SRST),
    .Tq(Tq),
    .Sampled_din(Sampled_din),
    .Transmit(TRANSMIT),
    .RXSTATES(RXSTATES),
    .TXen(TXen),
    .ID(ID_TX),
    .IDE(IDE_TX),
    .RTR(RTR_TX),
    .data(data_TX),
    .D_Len(D_Len_TX),
    .done(done_TX),
    .REC(REC),
    .TEC(TEC),
    .ErrState(ErrState),
    .TX(TX_from_trans),
    .req_Error(req_Error_TX),
    .imTX(imTX),
    .TXSTATES(TXSTATES)
);

Prescaler p1(.can_clk(CAN_CLK), .BRP(BRP), .Tq(Tq), .rst(CAN_RST));

Rengine rengine1 (
    .RXBUS(RXBUS),
    .RXSTATES(RXSTATES),
    .TXVALUE(TX),//have to check once is it TXfromtrans
    .TPROP(TPROP_Amender),
    .TSEG1(TSEG1_Amender),
    .TSEG2(TSEG2_Amender),
    .Tq(Tq),
    .rst(CAN_RST),
    .RXOUT(Sampled_din),
    .TXen(TXen),
    .RXen(RXen),
    .SJW(SJW_Amender)
);
assign SJW_Amender = (SJW == 0) ? 1 : 
                       ({1'b0,SJW} < TSEG1_Amender) ? ((SJW < 4) ? SJW : 4) : 
                       (TSEG1_Amender < 4) ? TSEG1_Amender[2:0] : 4;

RXMachine rx1 (
    .Tq(Tq),
    .rst(CAN_RST),
    .srst(SRST),
    .TOFILTERd(TOFILTERd),
    .TOFILTERI(TOFILTERI),
    .RXBUS(RXBUS),
    .D_Len(D_Len_rec),
    .req_Error(req_Error_RX),
    .IDE(IDE_rec),
    .AckTakeOver(AckTakeOver),
    .RXen(RXen),
    .TXen(TXen),
    .RTR(RTR_rec),
    .ErrState(ErrState),
    .OvlState(OvlState),
    .RXSTATES(RXSTATES),
    .done(done_RX),
    .imTX(imTX)
);

ErrorHandler err1 (
    .req_Error_RX(req_Error_RX),
    .req_Error_TX(req_Error_TX),
    .TXSTATES(TXSTATES),
    .RXSTATES(RXSTATES),
    .TXpin(TX_from_Err),
    .Tq(Tq),
    .rst(CAN_RST),
    .srst(SRST),
    .TEC(TEC),
    .REC(REC),
    .TXen(TXen),
    .imTX(imTX),
    .donefromtx(done_TX),
    .donefromrx(done_RX),
    .Sampled_din(Sampled_din),
    .ErrState(ErrState),
    .OvlState(OvlState)
);

APBCDC AC1 (
    .PCLK        (PCLK),
    .PRESETn     (PRESETn),
    .Tq          (Tq),
    .CAN_RST     (CAN_RST),
    .SRST        (SRST),
    .PSEL        (PSEL),
    .PENABLE     (PENABLE),
    .PWRITE      (PWRITE),
    .PADDR       (PADDR),
    .PWDATA      (PWDATA),
    .PREADY      (PREADY),
    .PSLVERR     (PSLVERR),
    .PRDATA      (PRDATA),
    .SJW         (SJW),
    .TPROP       (TPROP),
    .TSEG1       (TSEG1),
    .TSEG2       (TSEG2),
    .BRP         (BRP),
    .Mode        (Mode),
    .TRANSMIT    (TRANSMIT),
    .TXSTATES    (TXSTATES),
    .RTR_TX      (RTR_TX),
    .IDE_TX      (IDE_TX),
    .D_Len_TX    (D_Len_TX),
    .ID_TX       (ID_TX),
    .FULLDATA_TX (data_TX),
    .done_RX     (done_RX),
    .IDE_rec     (IDE_rec),
    .RTR_rec     (RTR_rec),
    .D_Len_rec   (D_Len_rec),
    .TOFILTERd   (TOFILTERd),
    .TOFILTERI   (TOFILTERI),
    .TEC         (TEC),
    .REC         (REC),
    .done_TX     (done_TX)
);

endmodule
//apply srst for RXMachine and TX